import{_ as e,o,c as r,a2 as s}from"./chunks/framework.BM5YPQmL.js";const a="/docs/screenshots/settings.png",u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1793529963000}'),i={name:"guide/settings.md"};function n(d,t,h,l,c,g){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Open the settings view using the <strong>settings</strong> tab in the header (route <code>/settings</code>). Settings are stored locally in your browser; json-tool never sends your data to a server.</p><p><img src="'+a+'" alt="Settings"></p><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h2><p>Configure the CodeMirror editor with the following options:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td>foldGutter</td><td>Show the fold gutter to collapse regions of the document</td></tr><tr><td>syntaxHighlighting</td><td>Highlight the JSON syntax</td></tr><tr><td>highlightActiveLine</td><td>Highlight the line that has the cursor</td></tr><tr><td>historyKeymap</td><td>Enable the history key bindings (undo/redo)</td></tr><tr><td>history</td><td>Keep the undo/redo history</td></tr><tr><td>autocompletion</td><td>Enable autocompletion</td></tr><tr><td>closeBrackets</td><td>Close brackets automatically</td></tr></tbody></table><p>The <strong>font size</strong> input controls the size of the text in the editors (<code>12px</code> by default).</p><p>Click <strong>Save</strong> to persist the changes. Editor changes take effect in the editors on the home, table and shape views.</p><blockquote><p>The indentation (the number of spaces used when formatting) is changed from the right toolbar in the <a href="/docs/guide/editor">editor</a>, not in the settings.</p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td>JSON History</td><td>When enabled (default), json-tool keeps a history of the JSON you have used and shows the history button in the header. The drawer lets you send an entry back to the editor or copy it.</td></tr></tbody></table><p>Feature changes are applied immediately, without requiring <strong>Save</strong>.</p>',12)])])}const b=e(i,[["render",n]]);export{u as __pageData,b as default};
